<script setup lang="ts">
/**
 * A heatmap showing magnitude over a grid (`design/components/heatmap.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/heatmap.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import {
  DEFAULT_GRID_MESSAGES,
  UNMEASURED,
  agentMember,
  chartMarks,
  chartPosition,
  chooseChartMark,
  createReading,
  createWarningLog,
  devWarning,
  heatmapModel,
  heatmapReadout,
  heatmapSelection,
  measureBox,
  readChartPosition,
  readingRest,
  readingView,
  scaleLegendSteps,
  useListening,
  type ChartMessages,
  type ChartTooltipConfig,
  type ChartXAxis,
  type HeatmapValue,
  type HeatmapYAxis,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/charts/heatmap.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartAxis from '@polymorph/recipes/charts/frame/chart-axis.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartScale from '@polymorph/recipes/charts/frame/chart-scale-legend.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button.vue'
import Table from '../structure/Table.vue'
import TableBody from '../structure/TableBody.vue'
import TableCell from '../structure/TableCell.vue'
import TableHead from '../structure/TableHead.vue'
import TableHeader from '../structure/TableHeader.vue'
import TableRow from '../structure/TableRow.vue'

export interface HeatmapProps {
  /**
   * One row per cell. A missing x×y combination shows the **surface**. A `null` value is an
   * absent cell, shown as — in the twin, and never a zero.
   */
  data: readonly Readonly<Record<string, string | number | null>>[]
  label: string
  loading?: boolean
  locale?: string
  /**
   * The chart tier's string catalog (`ChartMessages`). Defaults to generic English; a localized
   * host passes the same object to every chart.
   */
  messages?: ChartMessages
  size?: 'sm' | 'md' | 'lg'
  tooltip?: false | ChartTooltipConfig
  value: HeatmapValue
  x: ChartXAxis
  y: HeatmapYAxis
}

defineOptions({ name: 'Heatmap', inheritAttrs: false })

const props = withDefaults(defineProps<HeatmapProps>(), {
  loading: false,
  messages: () => DEFAULT_GRID_MESSAGES,
  size: 'md',
  tooltip: () => ({}),
})
const emit = defineEmits<{
  select: [selection: { x: string | number; y: string | number; value: number }]
}>()
const listening = useListening()
const box = ref(UNMEASURED)
const reading = ref(createReading({ count: 0, seriesStart: 0 }))
const position = ref(readingRest(0))
const twinOpen = ref(false)
const warningLog = ref(createWarningLog())
const frame = useTemplateRef<HTMLElement>('frame')
const plot = useTemplateRef<HTMLElement>('plot')
const input = computed(() => ({
  data: props.data,
  x: props.x,
  y: props.y,
  value: props.value,
  label: props.label,
  locale: props.locale,
  messages: props.messages,
  tooltip: props.tooltip,
  loading: props.loading,
  selectable: listening.select,
  box: box.value,
}))
const model = computed(() => heatmapModel(input.value))
const view = computed(() =>
  readingView(position.value, model.value.columns.length, model.value.rows.length),
)
const readout = computed(() => heatmapReadout(input.value, model.value, view.value))
const activate = computed(() => () => {
  const selection = heatmapSelection(input.value, model.value, reading.value.now())
  if (selection !== null) emit('select', selection)
})
const walk = computed(() => ({
  count: model.value.columns.length,
  seriesCount: model.value.rows.length,
  walkSeries: true,
  seriesStart: 0,
}))
const marks = computed(() => ({
  walk: walk.value,
  input: input.value,
  model: model.value,
  readout: heatmapReadout,
  selection: heatmapSelection,
}))
const onKey = computed(() => (event: KeyboardEvent) => {
  if (listening.select && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault()
    activate.value()
    return
  }
  reading.value.update(walk.value)
  if (reading.value.key(event.key)) event.preventDefault()
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    box.value = plot.value === null ? box.value : measureBox(plot.value, box.value)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [plot.value]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
const effect2 = () => {
  reading.value.subscribe((now) => {
    position.value = now
  })
}
onMounted(effect2)
const effect3 = () => {
  warningLog.value.log(model.value.warnings, (message) => devWarning(true, message))
}
onMounted(effect3)
watch(() => model.value.warnings.join('\n'), effect3, { flush: 'post' })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = !listening.select
    ? () => {}
    : agentMember({
        member: 'Heatmap',
        element: () => frame.value,
        state: () => ({
          items: chartMarks(marks.value, reading.value),
          position: chartPosition(marks.value, reading.value),
          count: walk.value.count,
        }),
        actions: {
          read: {
            argument: 'number',
            run: (value) => readChartPosition(marks.value, value, reading.value),
          },
          choose: {
            argument: 'id',
            run: (value) => chooseChartMark(marks.value, value, reading.value, activate.value),
          },
        },
      })
  release4 = () => {
    ran()
  }
}
onMounted(effect4)
onBeforeUnmount(() => release4?.())
</script>

<template>
  <figure
    ref="frame"
    :class="chartFrame.frame"
    :data-size="size"
    :data-state="model.state"
    :data-position="view.active ? view.index : undefined"
    :aria-label="label"
    data-member="heatmap"
  >
    <!-- region -->
    <div :class="chartFrame.region">
      <!-- y axis -->
      <div :class="chartFrame.yAxis">
        <!-- y axis ticks -->
        <div
          v-if="model.axes?.y !== undefined"
          :class="chartAxis.axis"
          data-orientation="y"
          aria-hidden="true"
        >
          <template v-for="tick in model.axes?.y ?? []" :key="tick.key">
            <span :class="chartAxis.tick" :style="{ top: `${tick.at}px` }" :data-align="tick.align">
              {{ tick.label }}
            </span>
          </template>
        </div>
      </div>
      <!-- plot -->
      <div ref="plot" :class="chartFrame.plot">
        <div v-if="model.state === 'empty'" :class="chartFrame.empty">
          <span>
            {{ messages.empty }}
          </span>
        </div>
        <!-- surface -->
        <div
          v-else
          :class="styles.surface"
          tabindex="0"
          role="img"
          :aria-label="label"
          @keydown="onKey($event)"
          @click="activate()"
          @pointerleave="reading.clear()"
          @blur="reading.clear()"
        >
          <!-- marks -->
          <svg
            v-if="model.plot !== null"
            :class="styles.marks"
            :width="model.plot?.width"
            :height="model.plot?.height"
            aria-hidden="true"
            focusable="false"
          >
            <!-- cells -->
            <g :class="styles.cells">
              <template v-for="cell in model.plot?.cells ?? []" :key="cell.key">
                <rect
                  :class="styles.cell"
                  :style="{ '--pm-chart-cell': cell.paint }"
                  :data-active="
                    view.index === cell.column && (view.series ?? 0) === cell.row ? '' : undefined
                  "
                  :x="cell.x"
                  :y="cell.y"
                  :width="cell.width"
                  :height="cell.height"
                  :rx="model.plot?.radius"
                />
              </template>
            </g>
            <!-- hits -->
            <g :class="styles.hits">
              <template v-for="hit in model.plot?.hits ?? []" :key="hit.key">
                <rect
                  :class="styles.hit"
                  :x="hit.x"
                  :y="hit.y"
                  :width="hit.width"
                  :height="hit.height"
                  @pointerenter="reading.moveTo(hit.column, hit.row)"
                />
              </template>
            </g>
          </svg>
        </div>
        <!-- tooltip -->
        <div
          v-if="readout.tooltip !== null"
          :class="chartTooltip.tooltip"
          :style="{
            '--pm-chart-tip-x': `${readout.tooltip?.x}px`,
            '--pm-chart-tip-y': `${readout.tooltip?.y}px`,
          }"
          :data-indicator="readout.tooltip?.indicator"
          :data-side="readout.tooltip?.side"
          aria-hidden="true"
        >
          <p v-if="readout.tooltip?.header !== undefined" :class="chartTooltip.header">
            {{ readout.tooltip?.header }}
          </p>
          <ul :class="chartTooltip.rows">
            <template v-for="row in readout.tooltip?.rows ?? []" :key="row.key">
              <li :class="chartTooltip.row">
                <span :class="chartTooltip.key" :style="{ '--pm-chart-key': row.paint }" />
                <span :class="chartTooltip.value">
                  {{ row.value }}
                </span>
                <span :class="chartTooltip.label">
                  {{ row.label }}
                </span>
              </li>
            </template>
          </ul>
        </div>
      </div>
      <!-- x axis -->
      <div :class="chartFrame.xAxis">
        <!-- x axis ticks -->
        <div
          v-if="model.axes?.x !== undefined"
          :class="chartAxis.axis"
          data-orientation="x"
          aria-hidden="true"
        >
          <template v-for="tick in model.axes?.x ?? []" :key="tick.key">
            <span
              :class="chartAxis.tick"
              :style="{ left: `${tick.at}px` }"
              :data-align="tick.align"
            >
              {{ tick.label }}
            </span>
          </template>
        </div>
      </div>
    </div>
    <template v-if="model.legend">
      <!-- scale legend -->
      <div
        v-if="model.scale.variant === 'diverging'"
        :class="chartScale.scale"
        data-variant="diverging"
      >
        <span :class="chartScale.band" aria-hidden="true">
          <template v-for="step in scaleLegendSteps('diverging')" :key="step.key">
            <span :class="chartScale.step" :style="{ background: step.paint }" />
          </template>
        </span>
        <span :class="chartScale.bounds">
          <span :class="chartScale.bound">
            {{ model.scale.min }}
          </span>
          <span :class="chartScale.bound">
            {{ model.scale.zero }}
          </span>
          <span :class="chartScale.bound">
            {{ model.scale.max }}
          </span>
        </span>
      </div>
      <!-- scale legend -->
      <div v-else :class="chartScale.scale">
        <span :class="chartScale.bound">
          {{ model.scale.min }}
        </span>
        <span :class="chartScale.ramp" aria-hidden="true">
          <template v-for="step in scaleLegendSteps('sequential')" :key="step.key">
            <span :class="chartScale.step" :style="{ background: step.paint }" />
          </template>
        </span>
        <span :class="chartScale.bound">
          {{ model.scale.max }}
        </span>
      </div>
    </template>
    <!-- summary -->
    <span :class="a11y.visuallyHidden">
      {{ model.summary }}
    </span>
    <!-- twin -->
    <div :class="chartTwin.twin" :data-state="twinOpen ? 'open' : 'closed'">
      <div :class="chartTwin.toggle">
        <Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="table"
          :iconOnly="true"
          :label="twinOpen ? messages.hideTable(label) : messages.showTable(label)"
          @click="twinOpen = !twinOpen"
        />
      </div>
      <div v-if="twinOpen" :class="chartTwin.table">
        <Table :label="messages.tableLabel(label)" :caption="messages.tableLabel(label)">
          <TableHead>
            <TableRow>
              <template v-for="column in model.twin.columns" :key="column.key">
                <TableHeader :numeric="column.numeric">
                  {{ column.label }}
                </TableHeader>
              </template>
            </TableRow>
          </TableHead>
          <TableBody>
            <template v-for="(row, line) in model.twin.rows" :key="line">
              <TableRow>
                <template
                  v-for="(cell, cellIndex) in row"
                  :key="model.twin.columns[cellIndex]?.key ?? cellIndex"
                >
                  <TableCell :numeric="model.twin.columns[cellIndex]?.numeric">
                    {{ cell === '' ? '—' : cell }}
                  </TableCell>
                </template>
              </TableRow>
            </template>
          </TableBody>
        </Table>
      </div>
    </div>
    <!-- live region -->
    <span :class="a11y.visuallyHidden">
      <div aria-live="polite" aria-atomic="true">
        {{ readout.announcement }}
      </div>
    </span>
  </figure>
</template>
